public sealed partial class NotificationManagementService(SoodalLifeDbContext db,IEnumerable<INotificationChannelSender> senders)
{
    private static readonly HashSet<string> AllowedVariables=["customer_name","provider_name","service_name","request_no","quote_no","transaction_no","scheduled_at","event_name","source_no","project_no","subscription_no"];

    public async Task<IReadOnlyList<NotificationTemplateResponse>> Templates(string? search,CancellationToken token)
    {var q=db.NotificationTemplates.AsNoTracking();if(!string.IsNullOrWhiteSpace(search)){var s=search.Trim();q=q.Where(x=>x.TemplateCode.Contains(s)||x.Name.Contains(s)||x.EventTypeCode.Contains(s));}return await q.OrderBy(x=>x.EventTypeCode).ThenBy(x=>x.TemplateCode).ThenBy(x=>x.ChannelCode).Select(x=>Template(x)).ToListAsync(token);}

    public async Task<NotificationTemplateResponse> Template(Guid id,CancellationToken token)
    {var template=await db.NotificationTemplates.AsNoTracking().SingleOrDefaultAsync(x=>x.PublicId==id,token)??throw NotFound("TEMPLATE_NOT_FOUND","알림 템플릿을 찾을 수 없습니다.");return Template(template);}

    public async Task<NotificationTemplateResponse> CreateTemplate(CreateNotificationTemplateRequest input,ClaimsPrincipal principal,CancellationToken token)
    {var actor=await UserId(principal,token);ValidateTemplate(input);if(await db.NotificationTemplates.AnyAsync(x=>x.TemplateCode==input.TemplateCode.Trim()&&x.ChannelCode==NormalizeChannel(input.ChannelCode),token))throw Conflict("TEMPLATE_DUPLICATED","같은 템플릿 코드와 채널이 이미 존재합니다.");var now=DateTime.UtcNow;var variables=Variables(input.TitleTemplate).Concat(Variables(input.BodyTemplate)).Distinct().Order().ToArray();var template=new NotificationTemplate{TemplateCode=input.TemplateCode.Trim(),Name=input.Name.Trim(),Description=Trim(input.Description),AudienceTypeCode=input.AudienceTypeCode.Trim().ToUpperInvariant(),EventTypeCode=input.EventTypeCode.Trim().ToUpperInvariant(),ChannelCode=NormalizeChannel(input.ChannelCode),TitleTemplate=input.TitleTemplate.Trim(),BodyTemplate=input.BodyTemplate.Trim(),AllowedVariablesJson=JsonSerializer.Serialize(variables),IsRequiredBusinessNotice=input.IsRequiredBusinessNotice,IsMarketing=input.IsMarketing,IsActive=true,EffectiveFrom=input.EffectiveFrom?.ToUniversalTime(),EffectiveTo=input.EffectiveTo?.ToUniversalTime(),CreatedAt=now,CreatedByUserId=actor,UpdatedAt=now,UpdatedByUserId=actor};db.NotificationTemplates.Add(template);await db.SaveChangesAsync(token);await Audit(actor,"NOTIFICATION_TEMPLATE_CREATED",template.PublicId,null,new{template.TemplateCode,template.ChannelCode},token);return Template(template);}

    public async Task<NotificationTemplateResponse> UpdateTemplate(Guid id,UpdateNotificationTemplateRequest input,ClaimsPrincipal principal,CancellationToken token)
    {var actor=await UserId(principal,token);ValidateTemplate(new(input.TemplateCode,input.Name,input.Description,input.AudienceTypeCode,input.EventTypeCode,input.ChannelCode,input.TitleTemplate,input.BodyTemplate,input.IsRequiredBusinessNotice,input.IsMarketing,input.EffectiveFrom,input.EffectiveTo));var template=await db.NotificationTemplates.SingleOrDefaultAsync(x=>x.PublicId==id,token)??throw NotFound("TEMPLATE_NOT_FOUND","알림 템플릿을 찾을 수 없습니다.");if(await db.NotificationTemplates.AnyAsync(x=>x.Id!=template.Id&&x.TemplateCode==input.TemplateCode.Trim()&&x.ChannelCode==NormalizeChannel(input.ChannelCode),token))throw Conflict("TEMPLATE_DUPLICATED","같은 템플릿 코드와 채널이 이미 존재합니다.");SetRowVersion(template,input.RowVersion);var before=new{template.TemplateCode,template.Name,template.EventTypeCode,template.ChannelCode,template.TitleTemplate,template.BodyTemplate,template.EffectiveFrom,template.EffectiveTo};template.TemplateCode=input.TemplateCode.Trim();template.Name=input.Name.Trim();template.Description=Trim(input.Description);template.AudienceTypeCode=input.AudienceTypeCode.Trim().ToUpperInvariant();template.EventTypeCode=input.EventTypeCode.Trim().ToUpperInvariant();template.ChannelCode=NormalizeChannel(input.ChannelCode);template.TitleTemplate=input.TitleTemplate.Trim();template.BodyTemplate=input.BodyTemplate.Trim();template.AllowedVariablesJson=JsonSerializer.Serialize(Variables(input.TitleTemplate).Concat(Variables(input.BodyTemplate)).Distinct().Order());template.IsRequiredBusinessNotice=input.IsRequiredBusinessNotice;template.IsMarketing=input.IsMarketing;template.EffectiveFrom=input.EffectiveFrom?.ToUniversalTime();template.EffectiveTo=input.EffectiveTo?.ToUniversalTime();template.UpdatedAt=DateTime.UtcNow;template.UpdatedByUserId=actor;await SaveConcurrent(token);await Audit(actor,"NOTIFICATION_TEMPLATE_UPDATED",id,before,new{template.TemplateCode,template.Name,template.EventTypeCode,template.ChannelCode,template.TitleTemplate,template.BodyTemplate,template.EffectiveFrom,template.EffectiveTo},token);return Template(template);}

    public async Task<NotificationTemplateResponse> SetTemplateStatus(Guid id,SetNotificationTemplateStatusRequest input,ClaimsPrincipal principal,CancellationToken token)
    {var actor=await UserId(principal,token);var template=await db.NotificationTemplates.SingleOrDefaultAsync(x=>x.PublicId==id,token)??throw NotFound("TEMPLATE_NOT_FOUND","알림 템플릿을 찾을 수 없습니다.");SetRowVersion(template,input.RowVersion);var before=template.IsActive;template.IsActive=input.IsActive;template.UpdatedAt=DateTime.UtcNow;template.UpdatedByUserId=actor;await SaveConcurrent(token);await Audit(actor,"NOTIFICATION_TEMPLATE_STATUS_CHANGED",id,new{isActive=before},new{template.IsActive},token);return Template(template);}

    public async Task<NotificationAdminSummary> Summary(CancellationToken token)
    {var today=DateTime.UtcNow.Date;return new(await db.Notifications.CountAsync(x=>x.RecordedAt>=today,token),await db.NotificationDeliveries.CountAsync(x=>x.StatusCode=="PENDING"||x.StatusCode=="PROCESSING",token),await db.NotificationDeliveries.CountAsync(x=>x.StatusCode=="SENT"||x.StatusCode=="DELIVERED",token),await db.NotificationDeliveries.CountAsync(x=>x.StatusCode=="FAILED",token),await db.NotificationRecipients.CountAsync(x=>x.ReadAt==null&&x.ArchivedAt==null&&db.NotificationDeliveries.Any(d=>d.NotificationRecipientId==x.Id&&d.ChannelCode=="WEB"),token));}

    public async Task<IReadOnlyList<NotificationDeliveryAdminItem>> Deliveries(string? status,CancellationToken token)
    {var q=from d in db.NotificationDeliveries.AsNoTracking() join n in db.Notifications.AsNoTracking() on d.NotificationId equals n.Id join r in db.NotificationRecipients.AsNoTracking() on d.NotificationRecipientId equals (long?)r.Id join u in db.Users.AsNoTracking() on r.UserId equals u.Id select new{d,n,r,u};if(!string.IsNullOrWhiteSpace(status))q=q.Where(x=>x.d.StatusCode==status);var rows=await q.OrderByDescending(x=>x.d.CreatedAt).Take(300).ToListAsync(token);return rows.Select(x=>new NotificationDeliveryAdminItem(x.d.PublicId,MaskUser(x.u),x.r.RecipientRoleCode,x.d.ChannelCode,x.n.TypeCode,x.d.StatusCode,x.d.ScheduledAt,x.d.CreatedAt,x.d.ErrorCode,x.d.ErrorMessage,x.d.RetryCount,x.d.AttemptedAt)).ToArray();}

    public async Task<ProcessOutboxNotificationResponse> ProcessOutbox(Guid id,CancellationToken token)
    {var outbox=await db.OutboxEvents.AsNoTracking().SingleOrDefaultAsync(x=>x.PublicId==id,token)??throw NotFound("OUTBOX_NOT_FOUND","업무 이벤트를 찾을 수 없습니다.");var eventType=outbox.EventType.ToUpperInvariant();var now=DateTime.UtcNow;var templates=await db.NotificationTemplates.Where(x=>x.EventTypeCode==eventType&&x.IsActive&&!x.IsMarketing&&(x.EffectiveFrom==null||x.EffectiveFrom<=now)&&(x.EffectiveTo==null||x.EffectiveTo>now)).OrderBy(x=>x.ChannelCode=="WEB"?0:1).ToListAsync(token);if(templates.Count==0)return new(id,0,0,0);var recipients=await ResolveRecipients(outbox,token);if(recipients.Count==0)return new(id,0,0,0);var variables=PayloadVariables(outbox);var nc=0;var rc=0;var dc=0;foreach(var group in templates.GroupBy(x=>x.TemplateCode)){var variants=group.ToList();var primary=variants.First();var eligible=new List<(long UserId,string Role)>();foreach(var userId in recipients.Distinct()){var role=await AudienceRole(userId,primary.AudienceTypeCode,token);if(role!=null)eligible.Add((userId,role));}if(eligible.Count==0)continue;var key=$"notification:outbox:{outbox.PublicId:N}:{primary.TemplateCode}";var existing=await db.Notifications.SingleOrDefaultAsync(x=>x.IdempotencyKey==key,token);if(existing!=null)continue;var title=Render(primary.TitleTemplate,variables);var body=Render(primary.BodyTemplate,variables);EnsureSafeContent(title,body);var notification=new Notification{RecipientUserId=eligible[0].UserId,TemplateId=primary.Id,TypeCode=eventType,PriorityCode=Priority(eventType),StatusCode="RECORDED",SourceTypeCode=outbox.AggregateType,SourcePublicId=outbox.AggregatePublicId,TargetTypeCode=outbox.AggregateType,TargetPublicId=outbox.AggregatePublicId,TemplateCodeSnapshot=primary.TemplateCode,Title=title,Body=body,DataJson=JsonSerializer.Serialize(new{sourceType=outbox.AggregateType,sourceId=outbox.AggregatePublicId}),IsUrgent=Priority(eventType)=="URGENT",RecordedAt=now,IdempotencyKey=key};await LinkSource(notification,outbox,token);db.Notifications.Add(notification);await db.SaveChangesAsync(token);nc++;foreach(var e in eligible){var recipient=new NotificationRecipient{NotificationId=notification.Id,UserId=e.UserId,RecipientRoleCode=e.Role,CreatedAt=now};db.NotificationRecipients.Add(recipient);await db.SaveChangesAsync(token);rc++;foreach(var variant in variants){if(!await ChannelEnabled(e.UserId,variant,token))continue;var delivery=new NotificationDelivery{NotificationId=notification.Id,NotificationRecipientId=recipient.Id,ChannelCode=variant.ChannelCode,AttemptNo=1,StatusCode=variant.ChannelCode=="WEB"?"DELIVERED":"PENDING",AttemptedAt=now,CompletedAt=variant.ChannelCode=="WEB"?now:null,DeliveredAt=variant.ChannelCode=="WEB"?now:null,RetryCount=0,CreatedAt=now,UpdatedAt=now};db.NotificationDeliveries.Add(delivery);await db.SaveChangesAsync(token);dc++;await Event(notification,"DELIVERY_QUEUED",$"notification-event:queued:{delivery.Id}",recipient.Id,delivery.Id,null,new{delivery.ChannelCode},token);}await Event(notification,"RECIPIENT_ADDED",$"notification-event:recipient:{recipient.Id}",recipient.Id,null,null,new{recipient.RecipientRoleCode},token);}await Event(notification,"CREATED",$"notification-event:created:{notification.Id}",null,null,null,new{outboxId=id},token);}return new(id,nc,rc,dc);}

    public async Task<NotificationDeliveryAdminItem> Retry(Guid id,ClaimsPrincipal principal,CancellationToken token)
    {var actor=await UserId(principal,token);var row=await(from d in db.NotificationDeliveries join n in db.Notifications on d.NotificationId equals n.Id join r in db.NotificationRecipients on d.NotificationRecipientId equals (long?)r.Id join u in db.Users on r.UserId equals u.Id where d.PublicId==id select new{d,n,r,u}).SingleOrDefaultAsync(token)??throw NotFound("DELIVERY_NOT_FOUND","발송 건을 찾을 수 없습니다.");var attemptNo=await db.NotificationDeliveryAttempts.CountAsync(x=>x.NotificationDeliveryId==row.d.Id,token)+1;var started=DateTime.UtcNow;var sender=senders.FirstOrDefault(x=>x.Supports(row.d.ChannelCode))??throw Conflict("CHANNEL_NOT_CONFIGURED","외부 발송 채널이 연동되지 않았습니다.");var result=await sender.SendAsync(new(row.n.PublicId,row.d.PublicId,row.d.ChannelCode,row.n.Title,row.n.Body),token);db.NotificationDeliveryAttempts.Add(new(){NotificationDeliveryId=row.d.Id,AttemptNo=attemptNo,StartedAt=started,CompletedAt=DateTime.UtcNow,ResultCode=result.ResultCode,ProviderResponseCode=result.ProviderResponseCode,FailureReason=result.FailureReason,CorrelationId=Guid.NewGuid(),CreatedAt=started});row.d.RetryCount++;row.d.AttemptNo=(short)Math.Min(short.MaxValue,attemptNo);row.d.AttemptedAt=started;row.d.CompletedAt=DateTime.UtcNow;row.d.UpdatedAt=DateTime.UtcNow;if(result.Success){row.d.StatusCode=result.ResultCode=="DELIVERED"?"DELIVERED":"SENT";row.d.SentAt=DateTime.UtcNow;row.d.DeliveredAt=result.ResultCode=="DELIVERED"?DateTime.UtcNow:null;row.d.ProviderMessageId=result.ExternalMessageId;row.d.ErrorCode=null;row.d.ErrorMessage=null;}else{row.d.StatusCode="FAILED";row.d.FailedAt=DateTime.UtcNow;row.d.ErrorCode=result.ResultCode;row.d.ErrorMessage=result.FailureReason;}await db.SaveChangesAsync(token);await Event(row.n,result.Success?"DELIVERY_SENT":"DELIVERY_FAILED",$"notification-event:attempt:{row.d.Id}:{attemptNo}",row.r.Id,row.d.Id,actor,new{result.ResultCode},token);await Audit(actor,"NOTIFICATION_DELIVERY_RETRIED",row.n.PublicId,null,new{deliveryId=id,result.ResultCode},token);return new(row.d.PublicId,MaskUser(row.u),row.r.RecipientRoleCode,row.d.ChannelCode,row.n.TypeCode,row.d.StatusCode,row.d.ScheduledAt,row.d.CreatedAt,row.d.ErrorCode,row.d.ErrorMessage,row.d.RetryCount,row.d.AttemptedAt);}

    public async Task<IReadOnlyList<NotificationListItem>> Mine(ClaimsPrincipal p,string view,CancellationToken token){var user=await UserId(p,token);var normalized=view.Trim().ToUpperInvariant();if(normalized is not("ALL"or"UNREAD"or"ARCHIVED"))throw Conflict("NOTIFICATION_VIEW_INVALID","알림 보기 조건을 확인해 주세요.");var q=from r in db.NotificationRecipients.AsNoTracking() join n in db.Notifications.AsNoTracking() on r.NotificationId equals n.Id where r.UserId==user select new{r,n};if(normalized=="UNREAD")q=q.Where(x=>x.r.ReadAt==null&&x.r.ArchivedAt==null);else if(normalized=="ARCHIVED")q=q.Where(x=>x.r.ArchivedAt!=null);else q=q.Where(x=>x.r.ArchivedAt==null);return await q.OrderByDescending(x=>x.n.RecordedAt).Select(x=>new NotificationListItem(x.n.PublicId,x.n.TypeCode,x.n.Title,x.n.Body,x.n.PriorityCode,x.n.StatusCode,x.n.TargetTypeCode,x.n.TargetPublicId,x.n.RecordedAt,x.r.ReadAt,x.r.ArchivedAt!=null)).Take(200).ToListAsync(token);}
    public async Task<NotificationUnreadCountResponse> Unread(ClaimsPrincipal p,CancellationToken token){var user=await UserId(p,token);return new(await db.NotificationRecipients.CountAsync(x=>x.UserId==user&&x.ReadAt==null&&x.ArchivedAt==null,token));}
    public async Task<NotificationListItem> Detail(Guid id,ClaimsPrincipal p,CancellationToken token){var user=await UserId(p,token);return await(from r in db.NotificationRecipients.AsNoTracking() join n in db.Notifications.AsNoTracking() on r.NotificationId equals n.Id where r.UserId==user&&n.PublicId==id select new NotificationListItem(n.PublicId,n.TypeCode,n.Title,n.Body,n.PriorityCode,n.StatusCode,n.TargetTypeCode,n.TargetPublicId,n.RecordedAt,r.ReadAt,r.ArchivedAt!=null)).SingleOrDefaultAsync(token)??throw NotFound("NOTIFICATION_NOT_FOUND","알림을 찾을 수 없습니다.");}
    public async Task Read(Guid id,ClaimsPrincipal p,CancellationToken token){var user=await UserId(p,token);var r=await Recipient(id,user,token);r.ReadAt??=DateTime.UtcNow;await db.SaveChangesAsync(token);await Event(await db.Notifications.SingleAsync(x=>x.Id==r.NotificationId,token),"READ",$"notification-event:read:{r.Id}",r.Id,null,user,null,token);}
    public async Task ReadAll(ClaimsPrincipal p,CancellationToken token){var user=await UserId(p,token);var rows=await db.NotificationRecipients.Where(x=>x.UserId==user&&x.ReadAt==null).ToListAsync(token);var now=DateTime.UtcNow;foreach(var r in rows)r.ReadAt=now;await db.SaveChangesAsync(token);foreach(var r in rows)await Event(await db.Notifications.SingleAsync(x=>x.Id==r.NotificationId,token),"READ",$"notification-event:read:{r.Id}",r.Id,null,user,new{all=true},token);}
    public async Task Archive(Guid id,ClaimsPrincipal p,CancellationToken token){var user=await UserId(p,token);var r=await Recipient(id,user,token);r.ArchivedAt??=DateTime.UtcNow;await db.SaveChangesAsync(token);await Event(await db.Notifications.SingleAsync(x=>x.Id==r.NotificationId,token),"ARCHIVED",$"notification-event:archived:{r.Id}",r.Id,null,user,null,token);}
    public async Task<IReadOnlyList<NotificationPreferenceResponse>> Preferences(ClaimsPrincipal p,CancellationToken token){var user=await UserId(p,token);return await db.NotificationPreferences.AsNoTracking().Where(x=>x.UserId==user).OrderBy(x=>x.EventGroupCode).Select(x=>new NotificationPreferenceResponse(x.EventGroupCode,x.WebEnabled,x.KakaoEnabled,x.SmsEnabled,x.EmailEnabled,x.PushEnabled,Convert.ToBase64String(x.RowVersion))).ToListAsync(token);}
    public async Task<NotificationPreferenceResponse> SetPreference(UpdateNotificationPreferenceRequest input,ClaimsPrincipal p,CancellationToken token){var user=await UserId(p,token);var row=await db.NotificationPreferences.SingleOrDefaultAsync(x=>x.UserId==user&&x.EventGroupCode==input.EventGroupCode,token);var now=DateTime.UtcNow;if(row==null){row=new(){UserId=user,EventGroupCode=input.EventGroupCode.Trim().ToUpperInvariant(),CreatedAt=now};db.NotificationPreferences.Add(row);}row.WebEnabled=input.WebEnabled;row.KakaoEnabled=input.KakaoEnabled;row.SmsEnabled=input.SmsEnabled;row.EmailEnabled=input.EmailEnabled;row.PushEnabled=input.PushEnabled;row.UpdatedAt=now;await db.SaveChangesAsync(token);return new(row.EventGroupCode,row.WebEnabled,row.KakaoEnabled,row.SmsEnabled,row.EmailEnabled,row.PushEnabled,Convert.ToBase64String(row.RowVersion));}

    private async Task<List<long>> ResolveRecipients(OutboxEvent o,CancellationToken token)
    {
        using var doc=JsonDocument.Parse(o.PayloadJson);var list=new List<long>();
        if(doc.RootElement.TryGetProperty("recipientUserId",out var one)&&one.TryGetInt64(out var uid))list.Add(uid);
        if(doc.RootElement.TryGetProperty("recipientUserIds",out var many)&&many.ValueKind==JsonValueKind.Array)foreach(var x in many.EnumerateArray())if(x.TryGetInt64(out uid))list.Add(uid);
        if(list.Count>0)return list;
        if(o.AggregateType=="Quote")list.AddRange(await(from q in db.Quotes join r in db.ServiceRequests on q.ServiceRequestId equals r.Id join c in db.CustomerProfiles on r.CustomerProfileId equals c.Id where q.PublicId==o.AggregatePublicId select c.UserId).ToListAsync(token));
        else if(o.AggregateType=="Transaction"){var pair=await(from t in db.Transactions join r in db.ServiceRequests on t.ServiceRequestId equals r.Id join c in db.CustomerProfiles on r.CustomerProfileId equals c.Id join p in db.ProviderProfiles on t.ProviderProfileId equals p.Id where t.PublicId==o.AggregatePublicId select new{Customer=c.UserId,Provider=p.UserId}).SingleOrDefaultAsync(token);if(pair!=null){list.Add(pair.Customer);list.Add(pair.Provider);}}
        else if(o.AggregateType=="AfterServiceCase"){var pair=await(from a in db.AfterServiceCases join c in db.CustomerProfiles on a.CustomerProfileId equals c.Id join p in db.ProviderProfiles on a.ProviderProfileId equals p.Id where a.PublicId==o.AggregatePublicId select new{Customer=c.UserId,Provider=p.UserId}).SingleOrDefaultAsync(token);if(pair!=null){list.Add(pair.Customer);list.Add(pair.Provider);}}
        else if(o.AggregateType=="DisputeCase"){var pair=await db.DisputeCases.Where(x=>x.PublicId==o.AggregatePublicId).Select(x=>new{x.ApplicantUserId,x.CounterpartyUserId}).SingleOrDefaultAsync(token);if(pair!=null){list.Add(pair.ApplicantUserId);list.Add(pair.CounterpartyUserId);}}
        else if(o.AggregateType=="InteriorProject"){var project=await db.InteriorProjects.SingleOrDefaultAsync(x=>x.PublicId==o.AggregatePublicId,token);if(project!=null){list.Add(await db.CustomerProfiles.Where(x=>x.Id==project.CustomerProfileId).Select(x=>x.UserId).SingleAsync(token));list.AddRange(await db.ProviderProfiles.Where(x=>x.Id==project.SelectedSiteVisitProviderId||x.Id==project.SelectedContractorProviderId).Select(x=>x.UserId).ToListAsync(token));}}
        else if(o.AggregateType=="SubscriptionContract"){var pair=await(from s in db.SubscriptionContracts join c in db.CustomerProfiles on s.CustomerProfileId equals c.Id join p in db.ProviderProfiles on s.ProviderProfileId equals p.Id where s.PublicId==o.AggregatePublicId select new{Customer=c.UserId,Provider=p.UserId}).SingleOrDefaultAsync(token);if(pair!=null){list.Add(pair.Customer);list.Add(pair.Provider);}}
        else if(o.AggregateType=="ChatRoom"&&doc.RootElement.TryGetProperty("messageId",out var messageValue)&&messageValue.TryGetGuid(out var messageId)){var sender=await(from m in db.ChatMessages join p in db.ChatParticipants on m.SenderParticipantId equals p.Id where m.PublicId==messageId select new{m.ChatRoomId,p.UserId}).SingleOrDefaultAsync(token);if(sender!=null)list.AddRange(await db.ChatParticipants.Where(x=>x.ChatRoomId==sender.ChatRoomId&&x.UserId!=sender.UserId&&x.StatusCode=="ACTIVE"&&x.AccessStartedAt<=DateTime.UtcNow&&(x.AccessEndedAt==null||x.AccessEndedAt>DateTime.UtcNow)).Select(x=>x.UserId).ToListAsync(token));}
        else if(o.AggregateType=="Sanction")list.AddRange(await db.Sanctions.Where(x=>x.PublicId==o.AggregatePublicId&&x.StatusCode!="DRAFT").Select(x=>x.TargetUserId).ToListAsync(token));
        return list.Distinct().ToList();
    }
    private static Dictionary<string,string> PayloadVariables(OutboxEvent o){var d=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase){["event_name"]=o.EventType,["source_no"]=o.AggregatePublicId.ToString("N")[..10].ToUpperInvariant()};using var doc=JsonDocument.Parse(o.PayloadJson);foreach(var p in doc.RootElement.EnumerateObject())if(AllowedVariables.Contains(p.Name)&&p.Value.ValueKind is JsonValueKind.String or JsonValueKind.Number)d[p.Name]=p.Value.ToString();return d;}
    private async Task LinkSource(Notification n,OutboxEvent o,CancellationToken token){switch(o.AggregateType){case"RequestDispatch":var dispatch=await db.RequestDispatches.Where(x=>x.PublicId==o.AggregatePublicId).Select(x=>new{x.Id,x.ServiceRequestId}).SingleOrDefaultAsync(token);if(dispatch!=null){n.RequestDispatchId=dispatch.Id;n.ServiceRequestId=dispatch.ServiceRequestId;}break;case"ServiceRequest":n.ServiceRequestId=await db.ServiceRequests.Where(x=>x.PublicId==o.AggregatePublicId).Select(x=>(long?)x.Id).SingleOrDefaultAsync(token);break;case"Quote":n.QuoteId=await db.Quotes.Where(x=>x.PublicId==o.AggregatePublicId).Select(x=>(long?)x.Id).SingleOrDefaultAsync(token);break;case"Transaction":n.TransactionId=await db.Transactions.Where(x=>x.PublicId==o.AggregatePublicId).Select(x=>(long?)x.Id).SingleOrDefaultAsync(token);break;case"AfterServiceCase":n.AfterServiceCaseId=await db.AfterServiceCases.Where(x=>x.PublicId==o.AggregatePublicId).Select(x=>(long?)x.Id).SingleOrDefaultAsync(token);break;case"DisputeCase":n.DisputeCaseId=await db.DisputeCases.Where(x=>x.PublicId==o.AggregatePublicId).Select(x=>(long?)x.Id).SingleOrDefaultAsync(token);break;case"Review":n.ReviewId=await db.Reviews.Where(x=>x.PublicId==o.AggregatePublicId).Select(x=>(long?)x.Id).SingleOrDefaultAsync(token);break;case"Sanction":n.SanctionId=await db.Sanctions.Where(x=>x.PublicId==o.AggregatePublicId).Select(x=>(long?)x.Id).SingleOrDefaultAsync(token);break;case"SubscriptionContract":n.SubscriptionContractId=await db.SubscriptionContracts.Where(x=>x.PublicId==o.AggregatePublicId).Select(x=>(long?)x.Id).SingleOrDefaultAsync(token);break;case"SubscriptionVisitSchedule":n.SubscriptionVisitScheduleId=await db.SubscriptionVisitSchedules.Where(x=>x.PublicId==o.AggregatePublicId).Select(x=>(long?)x.Id).SingleOrDefaultAsync(token);break;case"InteriorProject":n.InteriorProjectId=await db.InteriorProjects.Where(x=>x.PublicId==o.AggregatePublicId).Select(x=>(long?)x.Id).SingleOrDefaultAsync(token);break;}}
    private async Task<string?> AudienceRole(long user,string audience,CancellationToken token){var roles=await(from ur in db.UserRoles join r in db.Roles on ur.RoleId equals r.Id where ur.UserId==user&&ur.RevokedAt==null&&r.IsActive select r.Code).ToListAsync(token);return audience=="ALL"?roles.FirstOrDefault():roles.Contains(audience)?audience:null;}
    private async Task<bool> ChannelEnabled(long user,NotificationTemplate t,CancellationToken token){if(t.IsRequiredBusinessNotice)return true;var p=await db.NotificationPreferences.AsNoTracking().SingleOrDefaultAsync(x=>x.UserId==user&&x.EventGroupCode=="BUSINESS",token);return t.ChannelCode switch{"WEB"=>p?.WebEnabled??true,"KAKAO"=>p?.KakaoEnabled??true,"SMS"=>p?.SmsEnabled??false,"EMAIL"=>p?.EmailEnabled??false,"PUSH"=>p?.PushEnabled??false,_=>false};}
    private static string Render(string template,IReadOnlyDictionary<string,string> values)=>VariableRegex().Replace(template,m=>values.TryGetValue(m.Groups[1].Value,out var v)?v:throw Conflict("TEMPLATE_VARIABLE_VALUE_MISSING",$"{m.Groups[1].Value} 변수 값이 없습니다."));
    private static IEnumerable<string> Variables(string text)=>VariableRegex().Matches(text).Select(x=>x.Groups[1].Value);
    private static void ValidateTemplate(CreateNotificationTemplateRequest i){var audience=i.AudienceTypeCode.Trim().ToUpperInvariant();if(audience is not("CUSTOMER"or"PROVIDER"or"ADMIN"or"ALL"))throw Conflict("TEMPLATE_AUDIENCE_INVALID","알림 대상을 확인해 주세요.");_ = NormalizeChannel(i.ChannelCode);if(i.EffectiveFrom.HasValue&&i.EffectiveTo<=i.EffectiveFrom)throw Conflict("TEMPLATE_PERIOD_INVALID","템플릿 적용기간을 확인해 주세요.");var vars=Variables(i.TitleTemplate).Concat(Variables(i.BodyTemplate)).Distinct().ToArray();var invalid=vars.Where(x=>!AllowedVariables.Contains(x)).ToArray();if(invalid.Length>0)throw Conflict("TEMPLATE_VARIABLE_INVALID",$"허용되지 않은 변수입니다: {string.Join(", ",invalid)}");EnsureSafeContent(i.TitleTemplate,i.BodyTemplate);}
    private static void EnsureSafeContent(string title,string body){var text=title+" "+body;if(ScriptRegex().IsMatch(text)||SensitiveRegex().IsMatch(text))throw Conflict("NOTIFICATION_CONTENT_UNSAFE","알림에는 스크립트나 상세주소·전화번호·계좌·결제정보 등 민감정보를 포함할 수 없습니다.");}
    private static string NormalizeChannel(string c)=>c.Trim().ToUpperInvariant() switch{"IN_APP"=>"WEB","ALIMTALK"=>"KAKAO",var x when x is"WEB"or"KAKAO"or"SMS"or"EMAIL"or"PUSH"=>x,_=>throw Conflict("TEMPLATE_CHANNEL_INVALID","알림 채널을 확인해 주세요.")};
    private async Task<NotificationRecipient> Recipient(Guid notification,long user,CancellationToken token)=>await(from r in db.NotificationRecipients join n in db.Notifications on r.NotificationId equals n.Id where n.PublicId==notification&&r.UserId==user select r).SingleOrDefaultAsync(token)??throw NotFound("NOTIFICATION_NOT_FOUND","알림을 찾을 수 없습니다.");
    private async Task Event(Notification n,string type,string key,long? recipient,long? delivery,long? actor,object? data,CancellationToken token){if(await db.NotificationEvents.AnyAsync(x=>x.IdempotencyKey==key,token))return;var now=DateTime.UtcNow;db.NotificationEvents.Add(new(){NotificationId=n.Id,NotificationRecipientId=recipient,NotificationDeliveryId=delivery,ActorUserId=actor,EventTypeCode=type,IdempotencyKey=key,EventDataJson=data==null?null:JsonSerializer.Serialize(data),OccurredAt=now,CreatedAt=now});await db.SaveChangesAsync(token);}
    private async Task Audit(long actor,string action,Guid id,object? before,object? after,CancellationToken token){db.AuditLogs.Add(new(){OccurredAt=DateTime.UtcNow,ActorUserId=actor,ActorRoleCode="ADMIN",ActionCode=action,EntityType="Notification",EntityPublicId=id,ResultCode="SUCCESS",BeforeJson=before==null?null:JsonSerializer.Serialize(before),AfterJson=after==null?null:JsonSerializer.Serialize(after)});await db.SaveChangesAsync(token);}
    private void SetRowVersion(NotificationTemplate template,string? rowVersion){if(string.IsNullOrWhiteSpace(rowVersion))return;try{db.Entry(template).Property(x=>x.RowVersion).OriginalValue=Convert.FromBase64String(rowVersion);}catch(FormatException){throw Conflict("ROW_VERSION_INVALID","변경 버전 값이 올바르지 않습니다.");}}
    private async Task SaveConcurrent(CancellationToken token){try{await db.SaveChangesAsync(token);}catch(DbUpdateConcurrencyException){throw Conflict("CONCURRENCY_CONFLICT","다른 관리자가 먼저 변경했습니다. 새로고침 후 다시 시도해 주세요.");}}
    private async Task<long> UserId(ClaimsPrincipal p,CancellationToken token){if(!Guid.TryParse(p.FindFirstValue(ClaimTypes.NameIdentifier),out var id))throw new NotificationBusinessException(401,"AUTHENTICATION_REQUIRED","로그인이 필요합니다.");return await db.Users.Where(x=>x.PublicId==id&&x.StatusCode=="ACTIVE").Select(x=>x.Id).SingleAsync(token);}
    private static NotificationTemplateResponse Template(NotificationTemplate x)=>new(x.PublicId,x.TemplateCode,x.Name,x.Description,x.AudienceTypeCode,x.EventTypeCode,x.ChannelCode,x.TitleTemplate,x.BodyTemplate,JsonSerializer.Deserialize<string[]>(x.AllowedVariablesJson)??[],x.IsRequiredBusinessNotice,x.IsMarketing,x.IsActive,x.EffectiveFrom,x.EffectiveTo,Convert.ToBase64String(x.RowVersion));
    private static string MaskUser(User u)=>u.LoginId.Length<=2?"**":u.LoginId[..2]+new string('*',Math.Min(6,u.LoginId.Length-2));
    private static string? Trim(string? value)=>string.IsNullOrWhiteSpace(value)?null:value.Trim();
    private static string Priority(string type)=>type.Contains("URGENT")||type.Contains("FAILED")||type.Contains("DISPUTE")?"URGENT":"NORMAL";
    private static NotificationBusinessException NotFound(string c,string m)=>new(404,c,m);private static NotificationBusinessException Conflict(string c,string m)=>new(409,c,m);
    [GeneratedRegex(@"\{\{\s*([a-z0-9_]+)\s*\}\}",RegexOptions.IgnoreCase|RegexOptions.CultureInvariant)]private static partial Regex VariableRegex();
    [GeneratedRegex(@"<\s*script|javascript\s*:|onerror\s*=",RegexOptions.IgnoreCase|RegexOptions.CultureInvariant)]private static partial Regex ScriptRegex();
    [GeneratedRegex(@"\b01[016789][ -]?\d{3,4}[ -]?\d{4}\b|\b\d{6}[ -]?[1-4]\d{6}\b|상세주소|계좌번호|카드번호|CVC|주민번호",RegexOptions.IgnoreCase|RegexOptions.CultureInvariant)]private static partial Regex SensitiveRegex();
